			<a href="{{ paginateBase ~ pageNumber }}">{{ pageNumber }}</a>
		</li>
	{% endfor %}

	{% if pageInfo.nextUrl %}
		<li><a href="{{ pageInfo.nextUrl }}">Next Page</a></li>
	{% endif %}

	{% if pageInfo.currentPage != pageInfo.total %}
